{"copy":"<div class="row sectionBlockLayout" style="display: flex; flex-wrap: wrap; padding: 8px; margin: 0px; text-align: left; min-height: 100px;">
  <div class="container" style="display: flex; flex-wrap: wrap;">
    <div class="col-lg-12 columnBlockLayout" style="flex-grow: 1;min-width: 300px;display: flex;flex-direction: column;margin: 0;padding: 0;">{% entityform name: 'Unregister Attendee' %}</div>
  </div>
</div>","customcss":"div.navbar {
    display: none;
}
input#UpdateButton {
    display: none;
}
button.deactivate-link.btn-default.btn {
    width: 100%;
}
div#EntityFormPanel {
    background-color: #fff;
}
 .form-custom-actions {
    display: flex;
  }","customjavascript":"$(function(){
    $(".form-custom-actions").prepend("<div class='col-sm-6 clearfix'><div class='form-action-container-left'><button class='btn btn-secondary' id='cancelUnregisterButton'>Keep</button></div></div>");
    $("button.deactivate-link.btn-default.btn").addClass("btn-primary");

    $("#cancelUnregisterButton").click(function(e){
        e.preventDefault();
        window.parent.closeModal();
    });
    
    $(".deactivate-link.btn-default.btn.btn-primary").click(function(e){
        window.parent.location.href = "/my-registrations";
    });
})","displayorder":19,"enablerating":false,"enabletracking":false,"excludefromsearch":false,"feedbackpolicy":756150000,"hiddenfromsitemap":false,"isroot":false,"pagetemplateid":"4cc21211-5fcf-f111-a05a-70a8a52c89ad","parentpageid":"58120917-5fcf-f111-a05a-70a8a52c89ad","partialurl":"unregister-attendee","publishingstateid":"de110917-5fcf-f111-a05a-70a8a52c89ad","rootwebpageid":"91c21211-5fcf-f111-a05a-70a8a52c89ad","sharedpageconfiguration":true,"summary":"<p>This is sample landing page for you to start building your website</p>","title":"Unregister Attendee"}
